def transform(grid):
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if len(set(row[c] for row in grid)) == 1 and grid[0][c] not in (0,):
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            return [[2 if x != 0 and y != 0 else 0 for x,y in zip(rx,ry)] for rx,ry in zip(a,b)]
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            a, b = grid[:r], grid[r+1:]
            return [[2 if x != 0 and y != 0 else 0 for x,y in zip(rx,ry)] for rx,ry in zip(a,b)]
    raise ValueError('separator not found')
